<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$summary=$rows=[];if($pdo){$summary=$pdo->query('SELECT p.product_name,COUNT(c.id) clicks FROM affiliate_clicks c JOIN products p ON p.id=c.product_id GROUP BY c.product_id ORDER BY clicks DESC')->fetchAll();$rows=$pdo->query('SELECT p.product_name,c.referrer,c.created_at FROM affiliate_clicks c JOIN products p ON p.id=c.product_id ORDER BY c.created_at DESC LIMIT 200')->fetchAll();}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Affiliate Clicks</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Affiliate Click Reports</h1><p><a href="dashboard.php">Dashboard</a></p><section class="card"><h2>Summary</h2><table style="width:100%"><tr><th>Product</th><th>Clicks</th></tr><?php foreach($summary as $s):?><tr><td><?=e($s['product_name'])?></td><td><?=e((string)$s['clicks'])?></td></tr><?php endforeach;?></table></section><section class="card"><h2>Recent clicks</h2><table style="width:100%"><tr><th>Product</th><th>Referrer</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['product_name'])?></td><td><?=e($r['referrer']??'Direct')?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></section></main></body></html>
